import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'pg-data-types-l3-001', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Internals', question: 'How is JSONB stored internally in PostgreSQL?', options: ['As plain text', 'As a binary tree structure with sorted keys, allowing O(log n) key lookups', 'As a hash table', 'As XML'], correctAnswer: 1, explanation: 'JSONB is stored as a binary format where object keys are sorted. This allows efficient binary search for keys, making lookups much faster than parsing JSON text.', tags: ['data-types', 'jsonb', 'internals'] },
  { id: 'pg-data-types-l3-002', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Internals', question: 'What is the overhead of JSONB storage compared to JSON?', options: ['JSONB is always smaller', 'JSONB is slightly larger due to binary metadata (type tags, key offsets) but parses only once on input', 'They are the same size', 'JSON is always larger'], correctAnswer: 1, explanation: 'JSONB stores type information and offset pointers alongside the data, making it slightly larger than raw JSON text. The trade-off is faster processing since parsing happens only on input.', tags: ['data-types', 'jsonb', 'storage-overhead'] },
  { id: 'pg-data-types-l3-003', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Indexing', question: 'When should you use an expression index on a specific JSONB path instead of a GIN index?', options: ['Never', 'When you query a specific known path with equality or range comparisons, as a B-tree expression index is smaller and faster for that specific pattern', 'When the JSONB document is small', 'Only for text fields'], correctAnswer: 1, explanation: 'A B-tree index on (data->>\'email\') is more efficient than a GIN index when you only query that specific path. GIN is better when queries vary across different keys.', codeSnippet: "CREATE INDEX idx_email ON users ((data->>'email'));", tags: ['data-types', 'jsonb', 'expression-index'] },
  { id: 'pg-data-types-l3-004', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Path', question: 'What does the @? operator do with JSONB path expressions?', options: ['Pattern matching', 'Checks if a JSON path expression returns any item for the given JSONB value (equivalent to jsonb_path_exists)', 'Regex matching on paths', 'Type checking'], correctAnswer: 1, explanation: 'The @? operator is shorthand for jsonb_path_exists(). It returns true if the path expression matches any items.', codeSnippet: "SELECT data @? '$.items[*] ? (@.price > 100)'\nFROM products;", tags: ['data-types', 'jsonb', 'json-path', 'operator'] },
  { id: 'pg-data-types-l3-005', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Path', question: 'What does the @@ operator do with JSONB path expressions?', options: ['Full-text search', 'Returns the result of a JSON path predicate check as a boolean (the path must return a single boolean)', 'Pattern matching', 'Checks for containment'], correctAnswer: 1, explanation: 'The @@ operator applies a JSON path predicate and returns a boolean. Unlike @? which checks for existence, @@ evaluates the path expression as a boolean predicate.', codeSnippet: "SELECT data @@ '$.price > 100'\nFROM products;", tags: ['data-types', 'jsonb', 'json-path', 'predicate'] },
  { id: 'pg-data-types-l3-006', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Custom Types', question: 'How do you create a custom base type in PostgreSQL?', options: ['CREATE TYPE with columns only', 'Define input/output functions in C, then CREATE TYPE specifying those functions, internallength, and other properties', 'Use ALTER TABLE to add a type', 'Create a domain instead'], correctAnswer: 1, explanation: 'Creating a base type requires C functions for input (text->internal) and output (internal->text), plus the CREATE TYPE statement specifying these functions and storage details.', tags: ['data-types', 'custom-type', 'base-type'] },
  { id: 'pg-data-types-l3-007', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Custom Types', question: 'What is a shell type in PostgreSQL?', options: ['A type for shell commands', 'A placeholder type created by CREATE TYPE name; (without definition) that is referenced by I/O functions before the full type is defined', 'A temporary type', 'A type for scripting'], correctAnswer: 1, explanation: 'A shell type is a placeholder declaration that lets you reference the type name in I/O function definitions. The full type is defined afterward with CREATE TYPE ... (internallength = ...).', tags: ['data-types', 'custom-type', 'shell-type'] },
  { id: 'pg-data-types-l3-008', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Window Functions Advanced', question: 'What is the difference between ROWS BETWEEN 3 PRECEDING AND CURRENT ROW vs RANGE BETWEEN 3 PRECEDING AND CURRENT ROW?', options: ['They are identical', 'ROWS counts exactly 3 physical rows back; RANGE includes all rows whose ORDER BY value is within 3 units of the current value', 'RANGE counts 3 rows back', 'ROWS uses value comparison'], correctAnswer: 1, explanation: 'ROWS is a physical offset (exactly N rows). RANGE is a logical offset based on the ORDER BY value (e.g., for dates, RANGE 3 PRECEDING means dates within 3 units of the current date).', tags: ['functions', 'window', 'rows-vs-range', 'advanced'] },
  { id: 'pg-data-types-l3-009', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Text Search Advanced', question: 'What is a text search dictionary in PostgreSQL?', options: ['A dictionary file on disk', 'A module that normalizes tokens into lexemes, applying stemming, stop-word removal, or synonym expansion', 'A lookup table of words', 'A spell-checker'], correctAnswer: 1, explanation: 'Text search dictionaries process tokens from the parser and produce lexemes. Types include simple, synonym, thesaurus, ispell, and snowball (stemming) dictionaries.', tags: ['data-types', 'text-search', 'dictionary'] },
  { id: 'pg-data-types-l3-010', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Text Search Advanced', question: 'How do you create a custom text search configuration?', options: ['ALTER DEFAULT TEXT SEARCH', 'CREATE TEXT SEARCH CONFIGURATION, then ALTER to map token types to dictionaries', 'Modify the postgresql.conf file', 'Create a new locale'], correctAnswer: 1, explanation: 'Create a configuration (often copying an existing one), then alter the mapping of token types (word, email, url, etc.) to specific dictionaries for your use case.', codeSnippet: "CREATE TEXT SEARCH CONFIGURATION my_config (COPY = english);\nALTER TEXT SEARCH CONFIGURATION my_config\n  ALTER MAPPING FOR word WITH my_synonym, english_stem;", tags: ['data-types', 'text-search', 'custom-config'] },
  { id: 'pg-data-types-l3-011', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Text Search Advanced', question: 'What is ts_rank_cd() and how does it differ from ts_rank()?', options: ['They are identical', 'ts_rank_cd uses cover density ranking which considers the proximity of matching lexemes, producing better results for multi-word queries', 'ts_rank_cd is deprecated', 'ts_rank_cd is for case-sensitive ranking'], correctAnswer: 1, explanation: 'ts_rank_cd() (cover density) gives higher scores when matching words are closer together. ts_rank() considers only frequency. ts_rank_cd is generally preferred for relevance ranking.', tags: ['data-types', 'text-search', 'ranking', 'cover-density'] },
  { id: 'pg-data-types-l3-012', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Text Search Advanced', question: 'What is the setweight() function used for in text search?', options: ['Sets the search weight factor', 'Assigns a weight label (A, B, C, or D) to lexemes in a tsvector for relevance ranking', 'Sets column importance', 'Weights the query terms'], correctAnswer: 1, explanation: 'setweight() assigns priority labels to lexemes. Weight A is highest. You can combine vectors with different weights and ts_rank gives higher scores to higher-weighted matches.', codeSnippet: "UPDATE articles SET search_vector =\n  setweight(to_tsvector('english', title), 'A') ||\n  setweight(to_tsvector('english', body), 'B');", tags: ['data-types', 'text-search', 'setweight'] },
  { id: 'pg-data-types-l3-013', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Range Types Advanced', question: 'How do you create a custom range type?', options: ['It is not possible', 'Use CREATE TYPE ... AS RANGE specifying the subtype and optionally a subtype_diff function', 'Use ALTER TYPE to make any type a range', 'Use a domain on an existing range'], correctAnswer: 1, explanation: 'CREATE TYPE ... AS RANGE defines a new range type for any type with a B-tree operator class. A subtype_diff function enables GiST index support.', codeSnippet: "CREATE TYPE floatrange AS RANGE (\n  subtype = float8,\n  subtype_diff = float8mi\n);", tags: ['data-types', 'range', 'custom-range'] },
  { id: 'pg-data-types-l3-014', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Range Types Advanced', question: 'What is a multirange type in PostgreSQL 14+?', options: ['A range with multiple dimensions', 'A type that stores a set of non-overlapping, non-adjacent ranges as a single value', 'A range across multiple tables', 'A range with multiple bounds'], correctAnswer: 1, explanation: 'Multirange types (int4multirange, tsmultirange, etc.) store multiple disjoint ranges in a single value. They are automatically created for each range type.', codeSnippet: "SELECT '{[1,3), [7,10)}'::int4multirange;", tags: ['data-types', 'range', 'multirange', 'pg14'] },
  { id: 'pg-data-types-l3-015', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Range Types Advanced', question: 'What is the exclusion constraint with range types?', options: ['A foreign key on ranges', 'A constraint that prevents overlapping ranges using a GiST index and the && operator', 'A CHECK constraint for ranges', 'A NOT NULL constraint for ranges'], correctAnswer: 1, explanation: 'Exclusion constraints with ranges ensure no two rows have overlapping ranges. Combined with equality on other columns, they enforce rules like "no overlapping bookings for the same room."', codeSnippet: "CREATE TABLE reservations (\n  room_id int,\n  during tstzrange,\n  EXCLUDE USING gist (room_id WITH =, during WITH &&)\n);", tags: ['data-types', 'range', 'exclusion-constraint'] },
  { id: 'pg-data-types-l3-016', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Window Functions Advanced', question: 'How do you reference a previous window definition and add to it?', options: ['Use EXTEND WINDOW', 'Reference the named window in OVER and add additional clauses like ORDER BY or frame specification', 'Use INHERIT WINDOW', 'Use WINDOW ... LIKE'], correctAnswer: 1, explanation: 'You can reference a base window and extend it. The base window must not have a frame clause if the derived one adds ORDER BY.', codeSnippet: "SELECT id, val,\n  SUM(val) OVER (w ORDER BY id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)\nFROM t\nWINDOW w AS (PARTITION BY category);", tags: ['functions', 'window', 'derived-window'] },
  { id: 'pg-data-types-l3-017', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Advanced', question: 'How does a GIN index on JSONB work internally?', options: ['It indexes the JSON text', 'It creates index entries for each key, value, and key-value pair in the JSONB document, allowing fast lookups for containment and existence queries', 'It creates a single hash per document', 'It indexes only top-level keys'], correctAnswer: 1, explanation: 'A GIN index on JSONB (with default jsonb_ops) decomposes each JSONB document into individual key-value elements, creating inverted index entries for efficient searching.', tags: ['data-types', 'jsonb', 'gin-index', 'internals'] },
  { id: 'pg-data-types-l3-018', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Advanced', question: 'What is the difference between jsonb_ops and jsonb_path_ops GIN operator classes?', options: ['No difference', 'jsonb_ops indexes keys and values separately supporting ?, ?|, ?&, @>; jsonb_path_ops indexes key-value paths supporting only @> but with smaller index and faster lookups', 'jsonb_path_ops is slower', 'jsonb_ops only supports @>'], correctAnswer: 1, explanation: 'jsonb_path_ops creates a hash of the full path to each value, resulting in smaller indexes and faster containment checks. But it cannot support key existence operators.', tags: ['data-types', 'jsonb', 'gin-ops', 'path-ops'] },
  { id: 'pg-data-types-l3-019', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Custom Aggregates', question: 'How do you create a custom aggregate function in PostgreSQL?', options: ['CREATE FUNCTION with AGGREGATE keyword', 'CREATE AGGREGATE specifying the state transition function (sfunc), state type (stype), and optionally a final function (ffunc)', 'Extend an existing aggregate', 'Use PL/pgSQL loops'], correctAnswer: 1, explanation: 'CREATE AGGREGATE defines a custom aggregate by specifying: sfunc (updates state for each row), stype (state data type), and optionally ffunc (converts final state to result).', codeSnippet: "CREATE AGGREGATE array_accum(anyelement) (\n  sfunc = array_append,\n  stype = anyarray,\n  initcond = '{}'\n);", tags: ['functions', 'aggregate', 'custom-aggregate'] },
  { id: 'pg-data-types-l3-020', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Custom Aggregates', question: 'What is the purpose of the combinefunc in a parallel-safe aggregate?', options: ['Combines two result sets', 'Merges partial aggregate states from parallel workers into a single state', 'Combines input values', 'Joins two aggregates'], correctAnswer: 1, explanation: 'For parallel-safe aggregates, combinefunc merges two partial state values from different workers. Without it, the aggregate cannot be parallelized.', tags: ['functions', 'aggregate', 'parallel', 'combinefunc'] },
  { id: 'pg-data-types-l3-021', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'TOAST', question: 'What is TOAST in PostgreSQL?', options: ['A notification system', 'The Oversized-Attribute Storage Technique — a mechanism for storing large values that exceed the page size by compressing and/or storing them out-of-line', 'A type of index', 'A backup format'], correctAnswer: 1, explanation: 'TOAST handles values larger than ~2KB by compressing them and/or moving them to a separate TOAST table. This keeps the main table rows small enough to fit in pages.', tags: ['data-types', 'toast', 'storage'] },
  { id: 'pg-data-types-l3-022', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'TOAST', question: 'What are the TOAST storage strategies?', options: ['SMALL and LARGE', 'PLAIN (no TOAST), EXTENDED (compress then move out-of-line), EXTERNAL (move out-of-line without compressing), MAIN (compress but try to keep in-line)', 'INLINE and OUTLINE only', 'AUTO and MANUAL'], correctAnswer: 1, explanation: 'PLAIN: no TOAST allowed. EXTENDED: compress first, then move if still too large. EXTERNAL: move out-of-line uncompressed (good for already-compressed data). MAIN: compress but avoid moving.', codeSnippet: "ALTER TABLE t ALTER COLUMN data SET STORAGE EXTERNAL;", tags: ['data-types', 'toast', 'strategies'] },
  { id: 'pg-data-types-l3-023', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Advanced', question: 'How do you use JSONB subscript syntax (PostgreSQL 14+)?', options: ['Not supported', 'Access JSONB values directly using bracket notation like data[\'key\'] or data[0] for arrays', 'Using dot notation', 'Using -> only'], correctAnswer: 1, explanation: 'PostgreSQL 14+ supports JSONB subscripting: data[\'key\'] for object access, data[0] for array access. This also works in UPDATE SET assignments.', codeSnippet: "SELECT data['address']['city'] FROM users;\nUPDATE users SET data['name'] = '\"John\"' WHERE id = 1;", tags: ['data-types', 'jsonb', 'subscript', 'pg14'] },
  { id: 'pg-data-types-l3-024', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Collations', question: 'What is a collation in PostgreSQL and how does it affect text operations?', options: ['A data collection method', 'A set of rules that determine how strings are sorted and compared, based on locale settings', 'A method for collecting statistics', 'A way to group related tables'], correctAnswer: 1, explanation: 'Collations define the sort order and comparison behavior for string types. Different collations can give different results for ORDER BY and comparisons based on language rules.', codeSnippet: "SELECT * FROM users ORDER BY name COLLATE \"de_DE\";\nCREATE INDEX idx_name ON users (name COLLATE \"en_US\");", tags: ['data-types', 'collation', 'sorting'] },
  { id: 'pg-data-types-l3-025', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Collations', question: 'What is the ICU collation provider in PostgreSQL?', options: ['An internal component', 'An alternative to the OS-provided libc collation that offers deterministic behavior across platforms and more collation features', 'A color coding system', 'An index collation method'], correctAnswer: 1, explanation: 'ICU (International Components for Unicode) provides consistent collation behavior across all platforms. Unlike libc, ICU collations produce identical results regardless of OS, which is important for replication.', tags: ['data-types', 'collation', 'icu'] },
  { id: 'pg-data-types-l3-026', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Collations', question: 'What is a "nondeterministic" collation?', options: ['A random collation', 'A collation where strings that are canonically equivalent but have different byte representations are considered equal (e.g., case-insensitive or accent-insensitive)', 'A collation without an order', 'A collation that varies by session'], correctAnswer: 1, explanation: 'Nondeterministic collations (PostgreSQL 12+, ICU only) consider canonically equivalent strings as equal. This enables case-insensitive or accent-insensitive comparisons at the collation level.', codeSnippet: "CREATE COLLATION case_insensitive (\n  provider = icu,\n  locale = 'und-u-ks-level2',\n  deterministic = false\n);", tags: ['data-types', 'collation', 'nondeterministic'] },
  { id: 'pg-data-types-l3-027', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Window Functions Advanced', question: 'What is a "window function chain" or "nested window" pattern?', options: ['Chaining multiple OVER clauses', 'Using a subquery or CTE to apply window functions to the results of other window functions, since you cannot nest window functions directly', 'A linked list of windows', 'Chaining LAG and LEAD'], correctAnswer: 1, explanation: 'Window functions cannot reference other window functions directly. To compute a window function on window function results, wrap the first in a subquery or CTE.', codeSnippet: "WITH ranked AS (\n  SELECT *, ROW_NUMBER() OVER (ORDER BY score DESC) as rn\n  FROM students\n)\nSELECT *, LAG(score) OVER (ORDER BY rn) as prev_score\nFROM ranked;", tags: ['functions', 'window', 'chaining', 'pattern'] },
  { id: 'pg-data-types-l3-028', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Aggregate Functions Advanced', question: 'What is an ordered-set aggregate vs a hypothetical-set aggregate?', options: ['They are identical', 'Ordered-set aggregates (percentile_cont) compute over actual data; hypothetical-set aggregates (rank, dense_rank, percent_rank) compute where a hypothetical value would rank', 'Hypothetical aggregates are theoretical', 'Ordered-set uses HAVING'], correctAnswer: 1, explanation: 'Hypothetical-set aggregates like rank(value) WITHIN GROUP (ORDER BY col) compute what rank the given value would have if inserted into the ordered set.', codeSnippet: "SELECT rank(50000) WITHIN GROUP (ORDER BY salary)\nFROM employees;\n-- What rank would a $50000 salary have?", tags: ['functions', 'aggregate', 'hypothetical-set'] },
  { id: 'pg-data-types-l3-029', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Text Search Advanced', question: 'How does the websearch_to_tsquery() function differ from to_tsquery()?', options: ['It is for web development only', 'It accepts natural-language search syntax (like Google: quotes for phrases, - for NOT, OR for OR) instead of the strict tsquery syntax', 'It searches websites', 'It returns HTML results'], correctAnswer: 1, explanation: 'websearch_to_tsquery (PG 11+) converts user-friendly search input (like "fat cats" -dogs) into a tsquery. to_tsquery requires the strict & | ! <-> syntax.', codeSnippet: "SELECT websearch_to_tsquery('english', '\"fat cats\" -dogs');\n-- 'fat' <-> 'cat' & !'dog'", tags: ['data-types', 'text-search', 'websearch'] },
  { id: 'pg-data-types-l3-030', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Text Search Advanced', question: 'What is the GiST index trade-off vs GIN for full-text search?', options: ['GiST is always better', 'GiST is faster to build and update but slower for queries; GIN is slower to build but faster for lookups', 'GIN is faster to build', 'There is no difference'], correctAnswer: 1, explanation: 'GiST indexes are faster to build and handle updates well (no pending list) but have lossy matching requiring heap recheck. GIN indexes are larger and slower to update but provide faster exact lookups.', tags: ['data-types', 'text-search', 'gist-vs-gin'] },
  { id: 'pg-data-types-l3-031', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Advanced', question: 'What does jsonb_path_query_array() do?', options: ['Queries array elements only', 'Returns all items matching a JSON path expression as a single JSONB array (instead of multiple rows)', 'Creates a JSON array from a path', 'Queries arrays in JSONB'], correctAnswer: 1, explanation: 'jsonb_path_query_array() collects all JSON path matches into a single JSONB array, whereas jsonb_path_query() returns each match as a separate row.', codeSnippet: "SELECT jsonb_path_query_array(\n  '{\"items\":[{\"id\":1},{\"id\":2},{\"id\":3}]}'::jsonb,\n  '$.items[*].id'\n);\n-- Returns: [1, 2, 3]", tags: ['data-types', 'jsonb', 'json-path', 'array'] },
  { id: 'pg-data-types-l3-032', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Advanced', question: 'Can GIN indexes on JSONB support JSON path expressions (@? and @@ operators)?', options: ['No, separate indexes are needed', 'Yes, the default jsonb_ops and jsonb_path_ops GIN operator classes support @? and @@ for JSON path queries', 'Only with a special index type', 'Only btree indexes support path queries'], correctAnswer: 1, explanation: 'GIN indexes on JSONB columns support the @? and @@ operators for JSON path queries (PG 12+). The jsonb_path_ops class is particularly efficient for path containment checks.', tags: ['data-types', 'jsonb', 'json-path', 'gin-index'] },
  { id: 'pg-data-types-l3-033', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Custom Types', question: 'What is a polymorphic type in PostgreSQL?', options: ['A type that changes shape', 'A pseudo-type (anyelement, anyarray, anycompatible, etc.) used in function definitions to accept arguments of multiple types', 'A type with multiple columns', 'A type that stores multiple formats'], correctAnswer: 1, explanation: 'Polymorphic types like anyelement allow functions to work with any data type. The actual type is determined at call time, enabling generic/reusable functions.', tags: ['data-types', 'polymorphic', 'function-types'] },
  { id: 'pg-data-types-l3-034', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Custom Types', question: 'What is the anycompatible pseudo-type (PostgreSQL 13+)?', options: ['A compatibility check', 'A polymorphic type that resolves to the common type that all actual arguments can be implicitly cast to', 'A backward-compatible type', 'A type for cross-database queries'], correctAnswer: 1, explanation: 'anycompatible allows functions to accept arguments of different but compatible types. PostgreSQL finds the common type (e.g., int and float resolve to float).', tags: ['data-types', 'polymorphic', 'anycompatible', 'pg13'] },
  { id: 'pg-data-types-l3-035', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'TOAST', question: 'What is the TOAST threshold and can it be changed?', options: ['It is 8KB and cannot change', 'It is approximately TOAST_TUPLE_THRESHOLD (about 2KB by default) and cannot be changed without recompiling PostgreSQL', 'It is configurable per table', 'It is 1MB'], correctAnswer: 1, explanation: 'The TOAST threshold (~2KB, set by TOAST_TUPLE_THRESHOLD) is a compile-time constant. Values larger than this are compressed and/or stored out-of-line in the TOAST table.', tags: ['data-types', 'toast', 'threshold'] },
  { id: 'pg-data-types-l3-036', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Window Functions Advanced', question: 'How can you calculate a moving average with a window function?', options: ['Use a self-join', 'Use AVG() with a ROWS frame specification defining the window size', 'Use a recursive CTE', 'Use a stored procedure'], correctAnswer: 1, explanation: 'A moving average is calculated using AVG() with a ROWS frame that defines the lookback period.', codeSnippet: "SELECT date, price,\n  AVG(price) OVER (\n    ORDER BY date\n    ROWS BETWEEN 6 PRECEDING AND CURRENT ROW\n  ) as moving_avg_7day\nFROM stock_prices;", tags: ['functions', 'window', 'moving-average'] },
  { id: 'pg-data-types-l3-037', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Text Search Advanced', question: 'What are text search token types?', options: ['Only words', 'Categories assigned by the parser: word, email, url, host, sfloat, int, version, tag, etc.', 'Data type categories', 'Search result types'], correctAnswer: 1, explanation: 'The text search parser identifies different token types in the text. Each token type can be mapped to a different dictionary chain in the configuration.', tags: ['data-types', 'text-search', 'token-types'] },
  { id: 'pg-data-types-l3-038', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Advanced', question: 'How do you perform a deep merge of two JSONB objects (recursively merging nested objects)?', options: ['Using || (it only does shallow merge)', 'PostgreSQL has no built-in deep merge; you need a recursive PL/pgSQL function or use jsonb_set iteratively', 'Using MERGE keyword', 'Using jsonb_deep_merge()'], correctAnswer: 1, explanation: 'The || operator does shallow merge only — it replaces nested objects entirely. Deep merge requires a custom function that recursively processes nested objects.', tags: ['data-types', 'jsonb', 'deep-merge'] },
  { id: 'pg-data-types-l3-039', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Numeric Advanced', question: 'What happens when you divide two integers in PostgreSQL?', options: ['Returns a float', 'Returns an integer (truncated toward zero) — integer division', 'Returns a NUMERIC', 'Raises an error'], correctAnswer: 1, explanation: 'PostgreSQL performs integer division when both operands are integers: 7/2 = 3 (not 3.5). Cast one operand to get decimal division: 7::numeric/2 = 3.5.', codeSnippet: "SELECT 7/2;         -- Returns: 3 (integer division)\nSELECT 7.0/2;       -- Returns: 3.5000000000\nSELECT 7::numeric/2; -- Returns: 3.5000000000", tags: ['data-types', 'numeric', 'integer-division'] },
  { id: 'pg-data-types-l3-040', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Aggregate Functions Advanced', question: 'What is a moving aggregate in PostgreSQL?', options: ['An aggregate that moves between tables', 'An aggregate with an inverse transition function that efficiently removes values when the window frame advances, enabling O(1) per-row computation', 'An aggregate with LAG/LEAD', 'An aggregate with ORDER BY'], correctAnswer: 1, explanation: 'Moving aggregates use an msfunc (forward transition) and minvfunc (inverse/removal) to efficiently update the aggregate state as the window slides, avoiding recomputation.', tags: ['functions', 'aggregate', 'moving-aggregate'] },
  { id: 'pg-data-types-l3-041', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Text Search Advanced', question: 'What is the plainto_tsquery() function?', options: ['Creates a plain text copy', 'Converts plain text to a tsquery by AND-ing all the words together (no special syntax)', 'Creates an unweighted query', 'Removes formatting from a query'], correctAnswer: 1, explanation: 'plainto_tsquery converts plain text to a tsquery where all words are AND-ed together. Unlike to_tsquery, it does not interpret operators like & | !.', codeSnippet: "SELECT plainto_tsquery('english', 'fat cats and dogs');\n-- 'fat' & 'cat' & 'dog'  (and is a stop word)", tags: ['data-types', 'text-search', 'plainto-tsquery'] },
  { id: 'pg-data-types-l3-042', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Advanced', question: 'What is the jsonb_populate_record() function?', options: ['Populates a JSON document from a record', 'Expands a JSONB object into a PostgreSQL composite type, matching JSON keys to record field names', 'Records JSON changes', 'Creates a record from JSON schema'], correctAnswer: 1, explanation: 'jsonb_populate_record(base, jsonb) fills a record type with values from JSONB. Unmatched JSON keys are ignored; missing fields keep the base value or NULL.', codeSnippet: "SELECT * FROM jsonb_populate_record(\n  NULL::my_table,\n  '{\"id\":1,\"name\":\"John\",\"extra\":\"ignored\"}'::jsonb\n);", tags: ['data-types', 'jsonb', 'populate-record'] },
  { id: 'pg-data-types-l3-043', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Aggregate Functions Advanced', question: 'What does the GROUPING() function return?', options: ['The group name', 'A bitmask indicating which columns are aggregated (0 if the column is in the grouping, 1 if it is aggregated/NULL due to ROLLUP/CUBE)', 'The group size', 'The grouping level'], correctAnswer: 1, explanation: 'GROUPING(col) returns 0 if the column is part of the current grouping set, 1 if the column is being aggregated. This helps distinguish real NULLs from rollup NULLs.', codeSnippet: "SELECT department, year,\n  GROUPING(department) as g_dept,\n  GROUPING(year) as g_year,\n  SUM(sales)\nFROM orders\nGROUP BY ROLLUP(department, year);", tags: ['functions', 'aggregate', 'grouping-function'] },
  { id: 'pg-data-types-l3-044', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'TOAST', question: 'How does TOAST interact with MVCC?', options: ['TOAST tables do not use MVCC', 'Each TOAST chunk has its own xmin/xmax and TOAST data is never updated in place — new versions are created, and old versions are cleaned up by VACUUM', 'TOAST bypasses MVCC for performance', 'TOAST uses copy-on-write only'], correctAnswer: 1, explanation: 'TOAST tables are regular heap tables with MVCC. When a TOASTed column is updated, new TOAST chunks are created. If the TOASTed value is unchanged, the existing chunks are reused.', tags: ['data-types', 'toast', 'mvcc'] },
  { id: 'pg-data-types-l3-045', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'String Functions Advanced', question: 'What does the similarity() function from pg_trgm do?', options: ['Checks exact string equality', 'Returns a number between 0 and 1 indicating how similar two strings are based on shared trigrams', 'Compares similarity of table structures', 'Returns the edit distance'], correctAnswer: 1, explanation: 'similarity() from pg_trgm calculates the ratio of shared trigrams (3-character substrings) between two strings. 1 means identical, 0 means completely different.', codeSnippet: "CREATE EXTENSION pg_trgm;\nSELECT similarity('PostgreSQL', 'PostGreSQL');\n-- Returns: ~0.6", tags: ['functions', 'string', 'pg-trgm', 'similarity'] },
  { id: 'pg-data-types-l3-046', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'String Functions Advanced', question: 'What is the % operator from pg_trgm?', options: ['Modulo operation', 'Returns true if two strings have similarity above the pg_trgm.similarity_threshold', 'Percentage calculation', 'Wildcard matching'], correctAnswer: 1, explanation: 'The % operator (from pg_trgm) returns true if two strings are similar enough according to the configurable similarity threshold (default 0.3).', codeSnippet: "SET pg_trgm.similarity_threshold = 0.5;\nSELECT * FROM users WHERE name % 'Jhon';  -- finds 'John'", tags: ['functions', 'string', 'pg-trgm', 'operator'] },
  { id: 'pg-data-types-l3-047', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Advanced', question: 'What is the performance impact of large JSONB documents (>1MB)?', options: ['No impact', 'Large JSONB values are TOASTed, and any modification requires decompressing, modifying, and recompressing the entire document, making updates very expensive', 'They are stored more efficiently', 'PostgreSQL rejects them'], correctAnswer: 1, explanation: 'Large JSONB documents are TOAST-compressed. Any jsonb_set() or || modification requires detoasting the entire value, modifying it, and re-toasting — creating significant I/O and CPU overhead.', tags: ['data-types', 'jsonb', 'large-documents', 'performance'] },
  { id: 'pg-data-types-l3-048', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Text Search Advanced', question: 'What is a synonym dictionary in text search?', options: ['A dictionary of word meanings', 'A dictionary that replaces tokens with their synonyms before indexing, allowing searches to match equivalent terms', 'A dictionary of database terms', 'A dictionary for autocomplete'], correctAnswer: 1, explanation: 'A synonym dictionary maps tokens to replacement lexemes. For example, mapping "automobile" to "car" ensures both terms match the same documents.', codeSnippet: "-- In synonym file (my_synonyms.syn):\n-- automobile car\n-- vehicle car\nCREATE TEXT SEARCH DICTIONARY my_syn (\n  TEMPLATE = synonym,\n  SYNONYMS = my_synonyms\n);", tags: ['data-types', 'text-search', 'synonym-dictionary'] },
  { id: 'pg-data-types-l3-049', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Numeric Advanced', question: 'What is the pg_typeof() function?', options: ['Returns the PostgreSQL version', 'Returns the effective data type of any expression as regtype', 'Returns the type of a table', 'Returns the column type definition'], correctAnswer: 1, explanation: 'pg_typeof() returns the OID of the data type of its argument. It is useful for debugging type resolution issues.', codeSnippet: "SELECT pg_typeof(42);          -- integer\nSELECT pg_typeof(42.0);        -- numeric\nSELECT pg_typeof('hello');     -- unknown\nSELECT pg_typeof('hello'::text); -- text", tags: ['functions', 'type-inspection', 'pg-typeof'] },
  { id: 'pg-data-types-l3-050', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Custom Aggregates', question: 'What is a "final function" (ffunc) in a custom aggregate?', options: ['The last function called in a query', 'A function that transforms the aggregate state into the final result value after all rows have been processed', 'A function that finalizes the transaction', 'A cleanup function'], correctAnswer: 1, explanation: 'The ffunc takes the final state value after all rows and converts it to the output type. For example, an average aggregate might have state (sum, count) and ffunc returns sum/count.', tags: ['functions', 'aggregate', 'final-function'] },
  { id: 'pg-data-types-l3-051', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Advanced', question: 'How do you perform a left-recursive query on a JSONB tree structure?', options: ['Use JSON path only', 'Use a recursive CTE that extracts children from JSONB at each level', 'Use nested subqueries', 'Use a stored procedure loop'], correctAnswer: 1, explanation: 'Recursive CTEs can traverse JSONB tree structures by extracting child elements at each recursion level using jsonb_array_elements or jsonb_each.', codeSnippet: "WITH RECURSIVE tree AS (\n  SELECT data->>'name' as name, data->'children' as children\n  FROM root_nodes\n  UNION ALL\n  SELECT child->>'name', child->'children'\n  FROM tree, jsonb_array_elements(children) as child\n)\nSELECT * FROM tree;", tags: ['data-types', 'jsonb', 'recursive', 'tree'] },
  { id: 'pg-data-types-l3-052', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Window Functions Advanced', question: 'How do you calculate year-over-year growth using window functions?', options: ['Use a self-join only', 'Use LAG() with a partition by the grouping dimension to access the previous year value', 'Use a subquery for each year', 'Use ROLLUP'], correctAnswer: 1, explanation: 'LAG partitioned by the dimension and ordered by year gives access to the previous year value, enabling growth calculation.', codeSnippet: "SELECT year, revenue,\n  revenue - LAG(revenue) OVER (ORDER BY year) as growth,\n  ROUND((revenue - LAG(revenue) OVER (ORDER BY year))::numeric\n    / LAG(revenue) OVER (ORDER BY year) * 100, 1) as growth_pct\nFROM annual_revenue;", tags: ['functions', 'window', 'year-over-year'] },
  { id: 'pg-data-types-l3-053', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Arrays Advanced', question: 'How do you index an array column for containment queries?', options: ['B-tree index', 'GIN index', 'Hash index', 'BRIN index'], correctAnswer: 1, explanation: 'GIN indexes support array containment (@>, <@) and overlap (&&) operators. They decompose arrays into individual elements in the inverted index.', codeSnippet: "CREATE INDEX idx_tags ON articles USING gin(tags);", tags: ['data-types', 'arrays', 'gin-index'] },
  { id: 'pg-data-types-l3-054', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Collations', question: 'What problems can occur when the OS libc collation changes?', options: ['No problems', 'Indexes built with the old collation become corrupted because the sort order has changed, requiring REINDEX', 'Only display changes', 'Only new data is affected'], correctAnswer: 1, explanation: 'If a glibc update changes collation rules, B-tree indexes using that collation may become silently corrupted. PostgreSQL 15+ has COLLATION VERSION tracking to detect this.', tags: ['data-types', 'collation', 'index-corruption'] },
  { id: 'pg-data-types-l3-055', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Date/Time Advanced', question: 'What is the difference between statement_timestamp() and transaction_timestamp()?', options: ['They are identical', 'transaction_timestamp() returns the time at transaction start (same as NOW()); statement_timestamp() returns the time at the start of the current statement', 'statement_timestamp is more precise', 'transaction_timestamp is deprecated'], correctAnswer: 1, explanation: 'transaction_timestamp() (= NOW()) is fixed for the entire transaction. statement_timestamp() updates at the start of each statement. clock_timestamp() updates continuously.', tags: ['functions', 'date-time', 'timestamp-functions'] },
  { id: 'pg-data-types-l3-056', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Advanced', question: 'What is the jsonb_path_query_first() function?', options: ['Queries the first JSONB column', 'Returns the first item matching a JSON path expression, or NULL if no match', 'Queries the first element of a JSON array', 'Returns the first key in a JSON object'], correctAnswer: 1, explanation: 'jsonb_path_query_first() returns only the first matching item from a JSON path expression. It is useful when you expect a single result or want just the first match.', codeSnippet: "SELECT jsonb_path_query_first(\n  '{\"items\":[{\"id\":1},{\"id\":2}]}'::jsonb,\n  '$.items[*].id'\n);\n-- Returns: 1", tags: ['data-types', 'jsonb', 'json-path', 'first'] },
  { id: 'pg-data-types-l3-057', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Custom Types', question: 'What is an operator class and why is it needed for custom types?', options: ['A CSS class for operators', 'A set of operators and support functions that define how an index method can work with a particular data type', 'A class of SQL operators', 'A grouping of math operators'], correctAnswer: 1, explanation: 'Operator classes tell index methods (B-tree, GIN, GiST, etc.) how to compare and process values of a specific type. Custom types need custom operator classes for indexing support.', tags: ['data-types', 'custom-type', 'operator-class'] },
  { id: 'pg-data-types-l3-058', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Window Functions Advanced', question: 'What is the FILTER clause on a window aggregate?', options: ['Not supported for window functions', 'FILTER (WHERE ...) on a window aggregate limits which rows contribute to the aggregate within each frame', 'Same as WHERE', 'Only works with COUNT'], correctAnswer: 0, explanation: 'As of PostgreSQL 16, FILTER is supported on window aggregate functions, allowing conditional computation within the window frame.', tags: ['functions', 'window', 'filter'] },
  { id: 'pg-data-types-l3-059', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Aggregate Functions Advanced', question: 'What is the difference between array_agg(x ORDER BY y) and array_agg(x) with a window ORDER BY?', options: ['They are the same', 'The aggregate ORDER BY controls element order within each group; window ORDER BY controls partition ordering, which are independent concerns', 'Array order is always random', 'Only the aggregate ORDER BY matters'], correctAnswer: 1, explanation: 'Aggregate-level ORDER BY (inside the aggregate) controls the order of elements in the resulting array. This is independent of any ORDER BY in the OVER clause or outer query.', codeSnippet: "SELECT department,\n  array_agg(name ORDER BY salary DESC)\nFROM employees\nGROUP BY department;", tags: ['functions', 'aggregate', 'order-within-aggregate'] },
  { id: 'pg-data-types-l3-060', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Text Search Advanced', question: 'How do you implement autocomplete/prefix search with full-text search?', options: ['Use LIKE with prefix', 'Use the :* prefix matching operator in tsquery to match lexemes starting with a given prefix', 'Use pg_trgm only', 'Use a separate autocomplete table'], correctAnswer: 1, explanation: 'The :* suffix in tsquery performs prefix matching on lexemes. Combined with a GIN index, this enables efficient autocomplete functionality.', codeSnippet: "SELECT * FROM articles\nWHERE search_vector @@ to_tsquery('english', 'post:*');\n-- Matches: post, postgresql, postal, etc.", tags: ['data-types', 'text-search', 'prefix-search', 'autocomplete'] },
  { id: 'pg-data-types-l3-061', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Advanced', question: 'What are the limitations of JSONB indexing with GIN for range queries?', options: ['No limitations', 'GIN indexes on JSONB do not support range comparisons (>, <, BETWEEN) on values; you need an expression B-tree index on the specific path for range queries', 'GIN supports all query types', 'Only hash indexes work for ranges'], correctAnswer: 1, explanation: 'GIN indexes support containment and existence checks but not range comparisons on JSONB values. For queries like WHERE data->>\'age\' > \'30\', use a B-tree expression index.', codeSnippet: "-- For range queries on a specific JSONB path:\nCREATE INDEX idx_age ON users (((data->>'age')::int));", tags: ['data-types', 'jsonb', 'index-limitations', 'range-queries'] },
  { id: 'pg-data-types-l3-062', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Numeric Advanced', question: 'What is the difference between NUMERIC division and FLOAT division for precision?', options: ['They are identical', 'NUMERIC division maintains exact precision (limited by scale); FLOAT division can introduce rounding errors from IEEE 754 representation', 'FLOAT is more precise', 'NUMERIC always rounds to integers'], correctAnswer: 1, explanation: 'NUMERIC uses arbitrary-precision decimal arithmetic — exact within its declared precision. FLOAT uses IEEE 754 binary representation which cannot exactly represent many decimal fractions (e.g., 0.1).', tags: ['data-types', 'numeric', 'precision', 'float-vs-numeric'] },
  { id: 'pg-data-types-l3-063', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Aggregate Functions Advanced', question: 'What does the regr_r2() function calculate?', options: ['A regression result', 'The coefficient of determination (R-squared) of the linear regression, indicating how well the model fits the data', 'The second regression coefficient', 'Row number squared'], correctAnswer: 1, explanation: 'regr_r2() computes R-squared (0 to 1), where 1 means the regression line perfectly fits the data. It is calculated from the squared correlation coefficient.', tags: ['functions', 'aggregate', 'regression', 'r-squared'] },
  { id: 'pg-data-types-l3-064', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Date/Time Advanced', question: 'What is the make_date() function?', options: ['Creates a DATE column', 'Constructs a DATE value from year, month, and day integer components', 'Formats a date string', 'Converts text to date'], correctAnswer: 1, explanation: 'make_date(year, month, day) creates a DATE value from individual integer components. make_timestamp() and make_timestamptz() create timestamp values similarly.', codeSnippet: "SELECT make_date(2024, 3, 15);\n-- Returns: 2024-03-15", tags: ['functions', 'date-time', 'make-date'] },
  { id: 'pg-data-types-l3-065', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'String Functions Advanced', question: 'What does the levenshtein() function from fuzzystrmatch do?', options: ['Measures string length', 'Calculates the edit distance (minimum number of single-character edits) between two strings', 'Checks spelling', 'Finds common prefixes'], correctAnswer: 1, explanation: 'levenshtein() computes the minimum number of insertions, deletions, and substitutions needed to transform one string into another.', codeSnippet: "CREATE EXTENSION fuzzystrmatch;\nSELECT levenshtein('kitten', 'sitting');\n-- Returns: 3", tags: ['functions', 'string', 'levenshtein', 'fuzzystrmatch'] },
  { id: 'pg-data-types-l3-066', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'String Functions Advanced', question: 'What does the metaphone() function do?', options: ['Creates music', 'Generates a phonetic code for a string based on English pronunciation rules, useful for fuzzy name matching', 'Converts to morse code', 'Encrypts text'], correctAnswer: 1, explanation: 'metaphone() (from fuzzystrmatch) generates a code representing how a word sounds in English. Words that sound alike produce the same code.', codeSnippet: "SELECT metaphone('Smith', 10), metaphone('Smyth', 10);\n-- Both return: SM0", tags: ['functions', 'string', 'metaphone', 'phonetic'] },
  { id: 'pg-data-types-l3-067', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Range Types Advanced', question: 'What is the range_merge() function?', options: ['Merges range columns', 'Returns the smallest range that includes both input ranges (their bounding box)', 'Merges overlapping ranges', 'Combines range types'], correctAnswer: 1, explanation: 'range_merge(r1, r2) returns the smallest range that contains both input ranges, even if they do not overlap or are adjacent.', codeSnippet: "SELECT range_merge('[1,5)'::int4range, '[10,15)'::int4range);\n-- Returns: [1,15)", tags: ['data-types', 'range', 'merge'] },
  { id: 'pg-data-types-l3-068', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Advanced', question: 'How do you efficiently query JSONB arrays for elements matching a condition?', options: ['Use LIKE on the JSONB text', 'Use jsonb_array_elements() in a lateral join with filtering, or use JSON path expressions with filters', 'Loop through with PL/pgSQL', 'Convert to text array first'], correctAnswer: 1, explanation: 'Lateral join with jsonb_array_elements gives full SQL filtering power. JSON path expressions ($.items[*] ? (@.price > 10)) are more concise and can use GIN indexes.', codeSnippet: "-- Using lateral join:\nSELECT p.id, elem->>'name'\nFROM products p,\n  jsonb_array_elements(p.data->'items') elem\nWHERE (elem->>'price')::numeric > 10;\n\n-- Using JSON path:\nSELECT id, jsonb_path_query(data, '$.items[*] ? (@.price > 10)')\nFROM products;", tags: ['data-types', 'jsonb', 'array-query', 'lateral'] },
  { id: 'pg-data-types-l3-069', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Window Functions Advanced', question: 'Can you use aggregate functions (COUNT, SUM) as window functions?', options: ['No, they are separate', 'Yes, any standard aggregate can be used as a window function by adding OVER clause', 'Only COUNT works as a window function', 'Only with named windows'], correctAnswer: 1, explanation: 'All standard aggregate functions (COUNT, SUM, AVG, MIN, MAX, etc.) can be used as window functions by adding OVER(). They compute the aggregate across the window frame while keeping individual rows.', tags: ['functions', 'window', 'aggregate-as-window'] },
  { id: 'pg-data-types-l3-070', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Aggregate Functions Advanced', question: 'What is a "serialization function" in a custom aggregate?', options: ['Converts to JSON', 'Converts the aggregate state to bytea for transfer between parallel workers, paired with a deserialization function', 'Serializes the result', 'Converts to text format'], correctAnswer: 1, explanation: 'For parallel-safe aggregates with non-binary-safe state types, serialfunc/deserialfunc convert the state to/from bytea for inter-process communication.', tags: ['functions', 'aggregate', 'parallel', 'serialization'] },
  { id: 'pg-data-types-l3-071', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Date/Time Advanced', question: 'What is the ISODOW extraction from a date?', options: ['Day of week 0-6', 'ISO day of week (1=Monday through 7=Sunday), unlike DOW which uses 0=Sunday through 6=Saturday', 'Day of year', 'Day of decade'], correctAnswer: 1, explanation: 'EXTRACT(ISODOW FROM date) returns the ISO 8601 day of week (1=Monday, 7=Sunday). DOW returns 0=Sunday, 6=Saturday. ISODOW is usually more intuitive.', codeSnippet: "SELECT EXTRACT(DOW FROM DATE '2024-01-08');     -- 1 (Monday=1 in DOW)\nSELECT EXTRACT(ISODOW FROM DATE '2024-01-08'); -- 1 (Monday=1 in ISODOW)", tags: ['functions', 'date-time', 'isodow'] },
  { id: 'pg-data-types-l3-072', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Advanced', question: 'What does jsonb_set with create_if_missing parameter do?', options: ['Creates a table if missing', 'When true (default), creates the key if it does not exist; when false, only updates existing keys', 'Creates a JSONB column if missing', 'Handles missing JSONB documents'], correctAnswer: 1, explanation: 'jsonb_set(target, path, new_value, create_if_missing) with create_if_missing=true (default) creates intermediate keys. Set to false to only update existing paths.', codeSnippet: "SELECT jsonb_set('{\"a\":1}'::jsonb, '{b}', '2', true);\n-- Returns: {\"a\": 1, \"b\": 2}\nSELECT jsonb_set('{\"a\":1}'::jsonb, '{b}', '2', false);\n-- Returns: {\"a\": 1}  (b not created)", tags: ['data-types', 'jsonb', 'set', 'create-if-missing'] },
  { id: 'pg-data-types-l3-073', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Text Search Advanced', question: 'What is a thesaurus dictionary in PostgreSQL text search?', options: ['A word definition dictionary', 'A dictionary that replaces multi-word phrases with single tokens or synonyms during indexing', 'A list of word meanings', 'A cross-reference dictionary'], correctAnswer: 1, explanation: 'Thesaurus dictionaries can recognize and replace multi-word phrases. Unlike synonym dictionaries (single word), they can map "New York City" to "nyc".', tags: ['data-types', 'text-search', 'thesaurus'] },
  { id: 'pg-data-types-l3-074', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Custom Types', question: 'What is the pg_type catalog and what information does it contain?', options: ['A list of data type names', 'A system catalog storing all type definitions including storage details, input/output functions, alignment, TOAST strategy, and base type for domains', 'A type documentation table', 'A type validation table'], correctAnswer: 1, explanation: 'pg_type contains complete type metadata: OID, name, namespace, I/O functions, length, alignment, category (numeric, string, etc.), base type for domains, and more.', tags: ['data-types', 'catalog', 'pg-type'] },
  { id: 'pg-data-types-l3-075', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Numeric Advanced', question: 'What is the pg_lsn data type?', options: ['A logging sequence number', 'A data type representing a WAL Log Sequence Number, used for replication monitoring and point-in-time recovery', 'A lock sequence number', 'A local sequence number'], correctAnswer: 1, explanation: 'pg_lsn represents a position in the WAL stream. It supports subtraction (returns bytes between two positions) and comparison operators, useful for monitoring replication lag.', codeSnippet: "SELECT pg_current_wal_lsn();\nSELECT pg_wal_lsn_diff(pg_current_wal_lsn(), '0/0'::pg_lsn);", tags: ['data-types', 'pg-lsn', 'wal'] },
  { id: 'pg-data-types-l3-076', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Arrays Advanced', question: 'What is the performance characteristic of array containment (@>) with GIN index vs without?', options: ['GIN makes no difference', 'Without GIN: O(n*m) sequential scan checking each row array; with GIN: O(log n) inverted index lookup per element', 'GIN is slower for small arrays', 'Both are O(1)'], correctAnswer: 1, explanation: 'Without an index, PostgreSQL must scan every row and check each array. GIN creates inverted index entries for each element, enabling efficient lookups by element.', tags: ['data-types', 'arrays', 'gin-performance'] },
  { id: 'pg-data-types-l3-077', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Window Functions Advanced', question: 'What is the RESPECT NULLS vs IGNORE NULLS option in window functions?', options: ['Not supported in PostgreSQL', 'PostgreSQL does not support IGNORE NULLS for LAG/LEAD/FIRST_VALUE/LAST_VALUE (standard SQL feature); workarounds use FILTER or subqueries', 'It is the default behavior', 'Only for NTH_VALUE'], correctAnswer: 1, explanation: 'PostgreSQL does not yet support the IGNORE NULLS option for window functions (as of PG 16). Workarounds include using a subquery or array_agg with FILTER.', tags: ['functions', 'window', 'ignore-nulls', 'limitations'] },
  { id: 'pg-data-types-l3-078', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Advanced', question: 'How does JSONB handle numeric precision?', options: ['Same as JavaScript (64-bit float)', 'JSONB stores numeric values as PostgreSQL numeric type, preserving full precision without floating-point rounding', 'Numbers are stored as text', 'Limited to 32-bit integers'], correctAnswer: 1, explanation: 'JSONB stores numbers as PostgreSQL numeric type, maintaining exact decimal precision. This is different from many JSON implementations that use IEEE 754 floats.', tags: ['data-types', 'jsonb', 'numeric-precision'] },
  { id: 'pg-data-types-l3-079', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Aggregate Functions Advanced', question: 'What does the xmlagg() function do?', options: ['Aggregates XML schemas', 'Concatenates XML values from multiple rows into a single XML value', 'Creates an XML document', 'Validates XML'], correctAnswer: 1, explanation: 'xmlagg() is an aggregate function that concatenates XML values from multiple rows. Combined with xmlelement, it can build XML documents from relational data.', codeSnippet: "SELECT xmlelement(name items,\n  xmlagg(xmlelement(name item, name))\n) FROM products;", tags: ['functions', 'aggregate', 'xml'] },
  { id: 'pg-data-types-l3-080', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'String Functions Advanced', question: 'What does the convert_from() function do?', options: ['Converts from another database', 'Converts a binary string (bytea) from a specified encoding to the database encoding', 'Converts between data types', 'Converts from JSON to text'], correctAnswer: 1, explanation: 'convert_from(bytea, source_encoding) converts binary data from a specific encoding to the database encoding. convert_to() does the reverse.', codeSnippet: "SELECT convert_from(E'\\x48656c6c6f'::bytea, 'UTF8');\n-- Returns: Hello", tags: ['functions', 'string', 'encoding', 'convert'] },
  { id: 'pg-data-types-l3-081', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Range Types Advanced', question: 'How does the btree_gist extension help with range exclusion constraints?', options: ['It is not needed', 'btree_gist provides GiST index support for scalar types (int, text, etc.), enabling exclusion constraints that combine scalar equality with range overlap', 'It speeds up B-tree indexes', 'It provides GIN support for ranges'], correctAnswer: 1, explanation: 'Exclusion constraints require GiST. btree_gist adds GiST operator classes for standard scalar types, enabling constraints like EXCLUDE USING gist (room_id WITH =, during WITH &&).', codeSnippet: "CREATE EXTENSION btree_gist;\n-- Now room_id (integer) can use GiST with = operator", tags: ['data-types', 'range', 'btree-gist', 'exclusion'] },
  { id: 'pg-data-types-l3-082', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Date/Time Advanced', question: 'What is the justify_interval() function?', options: ['Adjusts text alignment', 'Normalizes an interval by converting 30 days to 1 month and 24 hours to 1 day', 'Validates an interval', 'Justifies the use of intervals'], correctAnswer: 1, explanation: 'justify_interval() adjusts an interval so that 30-day periods become months and 24-hour periods become days, producing more human-readable output.', codeSnippet: "SELECT justify_interval(INTERVAL '35 days 25 hours');\n-- Returns: 1 mon 5 days 01:00:00", tags: ['functions', 'date-time', 'justify-interval'] },
  { id: 'pg-data-types-l3-083', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Numeric Advanced', question: 'What is the pg_size_pretty() function?', options: ['Makes tables look pretty', 'Converts a byte count into a human-readable size string (KB, MB, GB, TB)', 'Formats numbers with commas', 'Returns the size of a pretty-printed value'], correctAnswer: 1, explanation: 'pg_size_pretty() converts a bigint byte count into a readable string like "100 MB" or "1.5 GB". Useful for displaying table and index sizes.', codeSnippet: "SELECT pg_size_pretty(pg_total_relation_size('my_table'));\n-- Returns: 1423 MB", tags: ['functions', 'utility', 'pg-size-pretty'] },
  { id: 'pg-data-types-l3-084', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'JSONB Advanced', question: 'What is the jsonb_insert() function?', options: ['Inserts a JSONB row', 'Inserts a new value into a JSONB array at a specified position, or adds a key to a JSONB object', 'Inserts JSONB into a table', 'Inserts a key into an index'], correctAnswer: 1, explanation: 'jsonb_insert(target, path, new_value, insert_after) inserts into arrays at the specified position. For objects, it adds the key if it does not exist (unlike jsonb_set which replaces).', codeSnippet: "SELECT jsonb_insert('[1,2,4]'::jsonb, '{2}', '3');\n-- Returns: [1, 2, 3, 4]", tags: ['data-types', 'jsonb', 'insert'] },
  { id: 'pg-data-types-l3-085', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Numeric Advanced', question: 'What does the scale() function return for NUMERIC values?', options: ['The display scale', 'The number of digits after the decimal point in the stored value', 'The column scale definition', 'The scaling factor'], correctAnswer: 1, explanation: 'scale(numeric) returns the number of decimal digits in the fractional part of the value. This is the actual stored scale, not the column definition.', codeSnippet: "SELECT scale(123.4500);\n-- Returns: 4", tags: ['functions', 'numeric', 'scale'] },
  { id: 'pg-data-types-l3-086', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Window Functions Advanced', question: 'What is the performance impact of using many different window specifications in one query?', options: ['No impact', 'Each distinct window specification may require a separate sort of the data, so multiple different PARTITION BY or ORDER BY clauses increase the query cost', 'It only affects memory', 'It is always optimized away'], correctAnswer: 1, explanation: 'PostgreSQL must sort data for each unique window specification. Queries with many different OVER clauses may need multiple sorts, which can be expensive for large datasets.', tags: ['functions', 'window', 'performance', 'multiple-windows'] },
  { id: 'pg-data-types-l3-087', language: 'postgresql', level: 'level3', category: 'Data Types & Functions', subcategory: 'Text Search Advanced', question: 'How do you debug text search configuration issues?', options: ['Use EXPLAIN', 'Use ts_debug() which shows how each token in a text is processed by the configured dictionaries', 'Check the PostgreSQL log', 'Use ts_validate()'], correctAnswer: 1, explanation: 'ts_debug() shows the complete processing pipeline for each token: the token type from the parser, which dictionaries are consulted, and the resulting lexemes.', codeSnippet: "SELECT * FROM ts_debug('english', 'The quick brown foxes');\n-- Shows each token, its type, dictionaries consulted, and resulting lexeme", tags: ['data-types', 'text-search', 'debugging', 'ts-debug'] },
];

